"use client";

import { FormEvent, useState } from "react";

const initialForm = {
  fullName: "",
  phone: "",
  email: "",
  service: "Installation",
  message: "",
  website: "",
};

export function InquiryForm() {
  const [form, setForm] = useState(initialForm);
  const [status, setStatus] = useState<"idle" | "sending" | "success" | "error">("idle");

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setStatus("sending");
    try {
      const response = await fetch("/api/inquiries", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      if (!response.ok) throw new Error("Unable to submit");
      setForm(initialForm);
      setStatus("success");
    } catch {
      setStatus("error");
    }
  }

  return (
    <form className="card space-y-4 p-5 sm:p-6" onSubmit={submit}>
      <div>
        <h2 className="text-2xl font-semibold">Request Service</h2>
        <p className="mt-1 text-sm text-slate-600">Tell us what you need and we will contact you shortly.</p>
      </div>
      <div className="grid gap-4 sm:grid-cols-2">
        <label className="text-sm font-medium">Full name *
          <input className="field mt-1 font-normal" required value={form.fullName} onChange={(event) => setForm({ ...form, fullName: event.target.value })} />
        </label>
        <label className="text-sm font-medium">Phone *
          <input className="field mt-1 font-normal" required type="tel" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} />
        </label>
        <label className="text-sm font-medium">Email *
          <input className="field mt-1 font-normal" required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} />
        </label>
        <label className="text-sm font-medium">Service needed *
          <select className="field mt-1 font-normal" value={form.service} onChange={(event) => setForm({ ...form, service: event.target.value })}>
            <option>Installation</option>
            <option>Service / Repair</option>
            <option>Maintenance</option>
            <option>Inspection</option>
            <option>Emergency</option>
          </select>
        </label>
        <label className="text-sm font-medium sm:col-span-2">How can we help? *
          <textarea className="field mt-1 min-h-28 font-normal" required value={form.message} onChange={(event) => setForm({ ...form, message: event.target.value })} />
        </label>
        <input aria-hidden="true" autoComplete="off" className="hidden" tabIndex={-1} value={form.website} onChange={(event) => setForm({ ...form, website: event.target.value })} />
      </div>
      <button className="button-primary w-full sm:w-auto" disabled={status === "sending"} type="submit">
        {status === "sending" ? "Sending..." : "Request Service"}
      </button>
      {status === "success" && <p className="text-sm font-medium text-green-700">Thank you. Your request was received.</p>}
      {status === "error" && <p className="text-sm font-medium text-red-700">Please call (732) 500-5428 for immediate help.</p>}
    </form>
  );
}
